"nx-panel-body" id="nx-theme-preview" style="background:<?= $e($profile['bg_color']) ?>;min-height:300px"><div class="nx-kicker">GOLDENSITE / IDENTIDAD</div><h2 style="font-size:28px;line-height:1.1;margin:32px 0 16px">Una presencia<br>con carácter propio.</h2><p class="nx-small">Contenido, estructura y detalles bajo tu control.</p><button type="button" id="nx-preview-button" style="margin-top:25px;padding:12px 22px;border:0;background:<?= $e($profile['primary_color']) ?>;color:#101317;border-radius:<?= $e($profile['border_radius']) ?>">Explorar el sitio ↗</button></div></section></div><section class="nx-panel"><div class="nx-panel-head"><h2><span class="nx-section-index">03</span>CSS de este estilo</h2><small>Hasta 24 KB</small></div><div class="nx-panel-body"><label>Estilos adicionales<textarea name="custom_css" rows="8" maxlength="24000" class="nx-code" spellcheck="false"><?= $e($profile['custom_css']) ?></textarea></label><p class="nx-note">Se aplica al sitio público. Los estilos no modifican la consola administrativa.</p></div></section><div class="nx-sticky-actions"><button class="nx-btn" type="submit" name="action" value="reset" onclick="return confirm('¿Restaurar la paleta original de este estilo?')">Restaurar estilo original</button><button class="nx-btn primary" type="submit">Guardar identidad visual ↗</button></div></form>
<script>document.querySelector('[name=primary_color]').addEventListener('input',e=>document.getElementById('nx-preview-button').style.background=e.target.value);document.querySelector('[name=bg_color]').addEventListener('input',e=>document.getElementById('nx-theme-preview').style.background=e.target.value);document.querySelector('[name=border_radius]').addEventListener('change',e=>document.getElementById('nx-preview-button').style.borderRadius=e.target.value);</script>
